using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using LighFight.Runtime;
// Test-only fork. Does not modify source importers, production prefab/material/catalog, geometry or UV.
public static class CourtyardPbrReviewBuilder {
 const string Source="Assets/LighFight/Art/Drafts/TripoCourtyard",Review="Assets/LighFight/Art/Drafts/TripoCourtyardPbrReview";
 static string Output=>Environment.GetEnvironmentVariable("LIGHTFIGHT_COURTYARD_QA_OUTPUT")??"CourtyardPbrEvidence";
 static string Hash(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 static Texture2D Map(string suffix,bool color,bool normal){string src=Source+"/courtyard-h31-original_"+suffix,dst=Review+"/Maps/"+suffix;byte[] raw=File.ReadAllBytes(src);Directory.CreateDirectory(Review+"/Maps");if(File.Exists(dst)){if(Hash(File.ReadAllBytes(dst))!=Hash(raw))throw new InvalidOperationException("Review source pixels differ: "+dst);}else File.WriteAllBytes(dst,raw);AssetDatabase.ImportAsset(dst,ImportAssetOptions.ForceSynchronousImport);var i=(TextureImporter)AssetImporter.GetAtPath(dst);i.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;i.sRGBTexture=color;i.isReadable=false;i.maxTextureSize=4096;i.textureCompression=TextureImporterCompression.Uncompressed;i.mipmapEnabled=true;i.filterMode=FilterMode.Bilinear;i.anisoLevel=1;i.SaveAndReimport();var t=AssetDatabase.LoadAssetAtPath<Texture2D>(dst);if(t.width!=4096||t.height!=4096)throw new Exception("Original4K dimension gate failed");return t;}
 static string Layout(GameObject root){return string.Join("\n",root.GetComponentsInChildren<Transform>(true).Select(t=>t.name+" "+t.localPosition.ToString("R")+" "+t.localRotation.ToString("R")+" "+t.localScale.ToString("R")));}
 public static void Build(){Directory.CreateDirectory(Output);Directory.CreateDirectory(Review);var shader=AssetDatabase.LoadAssetAtPath<Shader>(Review+"/CourtyardSourcePbr.shader");if(!shader)throw new Exception("Import packet shader at "+Review);var baseMap=Map("basecolor.jpg",true,false);var rm=Map("rm.jpg",false,false);var normal=Map("normal.png",false,true);string materialPath=Review+"/source-pbr-review.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(!mat){mat=new Material(shader);AssetDatabase.CreateAsset(mat,materialPath);}mat.shader=shader;mat.SetTexture("_MainTex",baseMap);mat.SetTexture("_RmTex",rm);mat.SetTexture("_BumpMap",normal);mat.SetFloat("_NormalStrength",1);mat.SetFloat("_NormalYSign",1);mat.SetFloat("_HideForeground",1);mat.SetFloat("_FrontCutZ",-2.3f);EditorUtility.SetDirty(mat);
 var source=AssetDatabase.LoadAssetAtPath<GameObject>(Source+"/arena.prefab");if(!source)throw new Exception("Original current arena prefab required");var buildScene=EditorSceneManager.NewPreviewScene();var actor=(GameObject)PrefabUtility.InstantiatePrefab(source,buildScene);try{PrefabUtility.UnpackPrefabInstance(actor,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);string before=Layout(actor);var meshes=actor.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh).ToArray();var bounds=new Bounds();bool first=true;long triangles=0;foreach(var f in actor.GetComponentsInChildren<MeshFilter>(true)){for(int n=0;n<f.sharedMesh.subMeshCount;n++)triangles+=f.sharedMesh.GetIndexCount(n)/3;foreach(var v in f.sharedMesh.vertices){var point=f.transform.TransformPoint(v);if(first){bounds=new Bounds(point,Vector3.zero);first=false;}else bounds.Encapsulate(point);}}if(triangles!=1922912)throw new Exception("Source topology count gate failed");foreach(var renderer in actor.GetComponentsInChildren<Renderer>(true))renderer.sharedMaterials=renderer.sharedMaterials.Select(_=>mat).ToArray();if(before!=Layout(actor)||!meshes.SequenceEqual(actor.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh)))throw new Exception("Geometry/transform changed");actor.name="Courtyard Original Source PBR Review";PrefabUtility.SaveAsPrefabAsset(actor,Review+"/arena-pbr-review.prefab");AssetDatabase.SaveAssets();var report=new List<string>{"source="+Source+"/arena.prefab","triangles="+triangles,"sourceMeshAssetIdentityUnchanged=True","sourceLayoutUnchanged=True","worldBoundsMin="+bounds.min.ToString("R"),"worldBoundsMax="+bounds.max.ToString("R"),"maps=4096x4096 source bytes unchanged; base=sRGB normal=NormalMap RM=linear Groughness/Bmetallic","ground=existing19,294-vertex flattening retained; no new floor edits","foregroundClip=existing worldY>.12/worldZ<-2.3 unchanged","phoneVerified=False","qualityAccepted=False"};foreach(var m in meshes)report.Add("mesh="+AssetDatabase.GetAssetPath(m)+" vertices="+m.vertexCount+" readable="+m.isReadable);File.WriteAllLines(Output+"/build-audit.txt",report);}finally{UnityEngine.Object.DestroyImmediate(actor);EditorSceneManager.ClosePreviewScene(buildScene);}Debug.Log("AGENT_RESULT test-only courtyard PBR fork built; geometry/UV/layout unchanged; no catalog promotion");}
 public static void Capture(){Build();if(QualitySettings.activeColorSpace!=ColorSpace.Linear)throw new Exception("Review requires current main Linear presentation");var filmic=Resources.Load<Shader>("Shaders/FittedFilmic");if(!filmic||!filmic.isSupported)throw new Exception("Current main filmic resource missing/unsupported");var scene=EditorSceneManager.NewPreviewScene();var root=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Review+"/arena-pbr-review.prefab"));EditorSceneManager.MoveGameObjectToScene(root,scene);var baseline=AssetDatabase.LoadAssetAtPath<Material>(Source+"/courtyard.mat");var original=AssetDatabase.LoadAssetAtPath<Material>(Review+"/source-pbr-review.mat");var cameraGo=new GameObject("Controlled arena camera");EditorSceneManager.MoveGameObjectToScene(cameraGo,scene);var c=cameraGo.AddComponent<Camera>();c.scene=scene;c.enabled=false;c.allowHDR=true;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.08f,.09f,.12f);var fx=cameraGo.AddComponent<FittedFilmicCamera>();fx.filmicShader=filmic;var lightGo=new GameObject("Fixed main-style key");EditorSceneManager.MoveGameObjectToScene(lightGo,scene);var key=lightGo.AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.2f;key.shadows=LightShadows.Soft;key.shadowStrength=.65f;key.shadowBias=.03f;key.shadowNormalBias=.2f;lightGo.transform.rotation=Quaternion.Euler(45,-30,0);var rt=new RenderTexture(1600,900,24,RenderTextureFormat.ARGBHalf,RenderTextureReadWrite.Linear);rt.Create();c.targetTexture=rt;var notes=new List<string>{"Editor preview captures, not Standalone/device performance","colorSpace="+QualitySettings.activeColorSpace,"HDR="+rt.format,"qualityShadowMode="+QualitySettings.shadows,"filmic="+fx.filmicShader.name+" supported="+fx.filmicShader.isSupported,"key=1.2 direction45/-30 ambientFlat(.45,.43,.4); exposure1","fixed source mesh/layout/maps; static frame, no actor/contact proof","candidate camera bookmarks are proposed only; no main camera edits"};bool oldAsync=ShaderUtil.allowAsyncCompilation;var oldAmbient=RenderSettings.ambientLight;var oldMode=RenderSettings.ambientMode;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.45f,.43f,.4f);var mats=new List<Material>();try{ShaderUtil.allowAsyncCompilation=false;foreach(string name in new[]{"baseline","pbr-no-normal","pbr","pbr-flip-y"}){var mat=new Material(name=="baseline"?baseline:original);mats.Add(mat);if(name=="pbr-no-normal")mat.SetFloat("_NormalStrength",0);if(name=="pbr-flip-y")mat.SetFloat("_NormalYSign",-1);foreach(var r in root.GetComponentsInChildren<Renderer>(true)){r.sharedMaterial=mat;r.receiveShadows=true;r.shadowCastingMode=ShadowCastingMode.On;}c.fieldOfView=42;c.transform.position=new Vector3(0,1.6f,-3.6f);c.transform.LookAt(new Vector3(0,1,0));Save(c,rt,Output+"/center-"+name+".png");if(name=="pbr"){c.transform.position=new Vector3(-2.4f,2.2f,-6.4f);c.transform.LookAt(new Vector3(-1,1,0));Save(c,rt,Output+"/framing-oblique-pbr.png");c.transform.position=new Vector3(0,1.6f,-5.8f);c.transform.LookAt(new Vector3(0,1,0));Save(c,rt,Output+"/framing-wide-pbr.png");mat.SetFloat("_HideForeground",0);c.fieldOfView=45;c.transform.position=new Vector3(-10,7,-14);c.transform.LookAt(new Vector3(0,1.2f,0));Save(c,rt,Output+"/reference-overview-pbr.png");mat.SetFloat("_HideForeground",1);}}File.WriteAllLines(Output+"/capture-scope.txt",notes);}finally{ShaderUtil.allowAsyncCompilation=oldAsync;RenderSettings.ambientLight=oldAmbient;RenderSettings.ambientMode=oldMode;c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);foreach(var m in mats)UnityEngine.Object.DestroyImmediate(m);UnityEngine.Object.DestroyImmediate(cameraGo);UnityEngine.Object.DestroyImmediate(lightGo);UnityEngine.Object.DestroyImmediate(root);EditorSceneManager.ClosePreviewScene(scene);}Debug.Log("AGENT_RESULT controlled courtyard material/framing captures complete; not quality acceptance");}
 static void Save(Camera camera,RenderTexture rt,string path){camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);try{image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(image);}}
}
